P.enemyTech=function(enemy,c){const list=[];for(const n of[enemy.signature,...(enemy.powers||[])].filter(Boolean)){const t={id:`e:${enemy.id}:${h32(n)}`,key:`e:${enemy.id}:${norm(n)}`,name:n,source:enemy.name,tags:[...new Set([...(enemy.tags||[]),...this.powerTags(n)])],mastery:5};t.cost=this.techniqueEnergyCost(t);const s=this.spec(t);if(s.energy<=c.enemyEnergy&&!c.enemyCooldowns?.[t.key])list.push({t,s})}if(!list.length)return{t:{key:'basic',name:'Basic Counterattack',tags:['physical'],source:enemy.name,mastery:5},s:{power:55,accuracy:.78,energy:0,cooldown:0,crit:.05,armorPen:0,guard:.1,heal:0,drain:0,recoil:0,effects:[]}};const f=this.fighter(c);for(const x of list){x.score=x.s.power*.7+x.s.accuracy*40-x.s.energy*.2+(f.hp/f.maxHP<.3?x.s.power*.1:0)+(Math.random()-.5)*6}return list.sort((a,b)=>b.score-a.score)[0]};
