P.directorEvent=function(){const tags=this.state.runStats.tags||[],count={};for(const t of tags)count[t]=(count[t]||0)+1;const top=Object.entries(count).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>x[0]);if(top.includes('reality')||top.includes('cosmic'))return{title:'COSMIC AUTHORITY NOTICE',desc:'Your repeated reality-scale power use has attracted an authority that normally ignores mortals.',choices:[['SUBMIT TO AUDIT','Lose 10% Energy; gain Mind.','audit'],['REFUSE JURISDICTION','Gain rare loot; Director heat rises.','defy']]};if(this.state.nemesis)return{title:'NEMESIS DEMANDS A REMATCH',desc:`${CHAR.get(this.state.nemesis.id)?.name} refuses to wait.`,choices:[['ACCEPT NOW','Immediate rematch.','rematch'],['DELAY','Recover HP; Nemesis levels up.','delay']]};if(this.state.kits.length>=8)return{title:'BORROWED POWER CASCADE',desc:'Too many incompatible systems resonate at once.',choices:[['STABILIZE','Raise mastery on several sets.','stable'],['FORCE EVOLUTION','Gain evolution; lose HP.','evolve']]};return{title:'A FUTURE VERSION OF YOU ARRIVES',desc:'They remember choices you have not made yet.',choices:[['ASK FOR TRAINING','Gain source skill points.','future'],['ASK FOR THE TRUTH','Gain Mind and reveal danger.','truth']]}};
