P.activityStart=function(mode){const p=this.state.pending,a=ACTIVITIES[p.ref],cost=Math.round(a.energy*(mode==='risk'?1.25:mode==='safe'?.7:1));if(this.state.energyPool<cost)return this.toast(`Need ${cost} Energy.`);this.state.energyPool-=cost;p.mini={mode,step:0,score:0,rows:CHAL[a.category]||CHAL.Race};this.renderAll()};
